  credentials: true
}));
```

#### 5. Poor Error Handling
**Issue**: Default Express error handling could leak stack traces and internal details.

**Recommendation**: Implement proper error handling.

```javascript
// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: 'The requested resource does not exist'
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(err.stack); // Log for internal monitoring

  // Don't leak stack trace in production
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production' 
