### 2. Improved Secrets Management Implementation

Here's how to properly manage secrets in a Node.js application:

```javascript
// config/secrets.js - Centralized secrets management
require('dotenv').config(); // Load .env file (only in development)

const requiredSecrets = [
  'ACCESS_TOKEN_SECRET',
  'REFRESH_TOKEN_SECRET',
  'DATABASE_URL',
  'API_KEY_SECRET'
];

// Validate required secrets exist in production
const validateSecrets = () => {
  if (process.env.NODE_ENV === 'production') {
    const missing = requiredSecrets.filter(secret => !process.env[secret]);
    if (missing.length > 0) {
      throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
    }
  }
};

validateSecrets(); // Run validation on module load

const secrets = {
  // JWT Secrets
  accessTokenSecret: process.env.ACCESS_TOKEN_SECRET,
  refreshTokenSecret: process.env.REFRESH_TOKEN_SECRET,

  // Database
  databaseUrl: process.env.DATABASE_URL,

  // API Keys
  apiKeySecret: process.env.API_KEY_SECRET,

  // Application
  port: process.env.PORT || 3000,
  nodeEnv: process.env.NODE_ENV || 'development',

  // External Services
  externalApiUrl: process.env.EXTERNAL_API_URL,
  externalApiKey: process.env.EXTERNAL_API_KEY

  // Add more as needed
};

// Utility function to safely get secrets with fallback ONLY in development
const getSecret = (key, defaultValue = null) => {
  const value = process.env[key];

  if (value !== undefined && value !== '') {
    return value;
  }

  if (defaultValue !== null && process.env.NODE_ENV !== 'production') {
    console.warn(`Using default value for ${key} - ONLY FOR DEVELOPMENT`);
    return defaultValue;
  }

  if (process.env.NODE_ENV === 'production') {
    throw new Error(`Missing required secret: ${key}`);
  }

  return defaultValue;
};

module.exports = { secrets, getSecret };
```

### 3. Proper .env.example File (Never commit actual .env)

Create a `.env.example` file:
```env
# Copy this to .env and fill in your actual values
# NEVER commit .env to version control

NODE_ENV=development
PORT=3000

# JWT Secrets (generate strong random values)
