  // In a real application, you would filter data based on user permissions
  // For now, returning static data as in original
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

