# Dotenv Usage Security Guidance

## Potential Issues with Dotenv in Applications

While I cannot review the actual contents of `.env` files for security reasons, I can provide guidance on secure usage patterns based on the code review.

### Secure Dotenv Implementation Patterns

#### 1. Loading Order and Override Prevention
```javascript
// SECURE: Load .env early, but prevent override by process.env
require('dotenv').config({ 
  path: `.env.${process.env.NODE_ENV || 'development'}`, 
  override: false  // Prevent .env from overriding actual environment variables
});

// Even better: Explicitly specify which files to load
const envFiles = [
  `.env.${process.env.NODE_ENV}.local`,  # Highest priority (but gitignored)
  `.env.${process.env.NODE_ENV}`,        # Environment specific
  '.env.local',                          # Local overrides (gitignored)
  '.env'                                 # Default (checked into repo as template only)
];

// Load in order, later files override earlier ones
envFiles.forEach(file => {
  try {
    require('dotenv').config({ path: file, override: true });
  } catch (error) {
    // File doesn't exist, continue
    if (error.code !== 'ENOENT') {
      throw error;
    }
  }
});
```

#### 2. Environment Variable Validation
```javascript
// Validate critical environment variables
function validateEnvVars() {
  const required = [
    'NODE_ENV',
    'PORT',
    'DATABASE_URL',
    'JWT_SECRET',
    'API_KEY'
  ];

  const missing = required.filter(key => !process.env[key]);

  if (missing.length > 0) {
    throw new Error(
      `Missing required environment variables: ${missing.join(', ')}. ` +
      'Please check your .env file or environment configuration.'
    );
  }

  // Additional validation
  if (!['development', 'test', 'production'].includes(process.env.NODE_ENV)) {
    throw new Error('NODE_ENV must be development, test, or production');
  }

  const port = parseInt(process.env.PORT, 10);
  if (isNaN(port) || port < 1 || port > 65535) {
    throw new Error('PORT must be a valid port number (1-65535)');
  }
}

// Call validation early in application startup
try {
  validateEnvVars();
} catch (error) {
  console.error('Fatal configuration error:', error.message);
  process.exit(1);
}
```

#### 3. Preventing Accidental Exposure in Logs
```javascript
// Utility to safely log objects that might contain secrets
function safeLog(obj, secretsMask = ['password', 'secret', 'key', 'token', 'auth']) {
  if (typeof obj !== 'object' || obj === null) {
    return obj;
  }

  const masked = {};
  for (const [key, value] of Object.entries(obj)) {
    const lowerKey = key.toLowerCase();
    const isSecret = secretsMask.some(secret => lowerKey.includes(secret));

    if (isSecret) {
      masked[key] = '[REDACTED]';
    } else if (typeof value === 'object' && value !== null) {
      masked[key] = safeLog(value, secretsMask);
    } else {
      masked[key] = value;
    }
  }

  return masked;
}

// Usage example:
// console.log('Database config:', safeLog(dbConfig));
