// Custom validation for common attack patterns
const validateNoNoSqlInjection = (req, res, next) => {
  // Recursively check for dangerous MongoDB operators
  const dangerousOps = ['$where', '$ne', '$gte', '$lte', '$in', '$nin', '$regex', '$options'];

  function checkObject(obj) {
    if (typeof obj !== 'object' || obj === null) return true;

    for (const key of Object.keys(obj)) {
      if (key.startsWith('$') && dangerousOps.includes(key)) {
        return false;  // Found dangerous operator
      }
      if (typeof obj[key] === 'object' && obj[key] !== null) {
        if (!checkObject(obj[key])) return false;
      }
    }
    return true;
  }

  // Check body, query, and params
  if (!checkObject(req.body) || !checkObject(req.query) || !checkObject(req.params)) {
    return res.status(400).json({ 
      error: 'Bad Request',
      message: 'Invalid input detected' 
    });
  }

  next();
};

// Apply validation globally or to specific routes
app.use(validateNoNoSqlInjection);

// Custom sanitization middleware
const sanitizeInput = (req, res, next) => {
  // Sanitize string inputs to prevent XSS
  const sanitizeString = (str) => {
    if (typeof str !== 'string') return str;
    return str
      .replace(/[&<>"']/g, tag => 
        ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#x27;' }[tag])
      );
  };

  // Recursively sanitize objects
  const sanitizeObject = (obj) => {
    if (typeof obj !== 'object' || obj === null) return obj;

    if (Array.isArray(obj)) {
      return obj.map(sanitizeObject);
    }

    const sanitized = {};
    for (const [key, value] of Object.entries(obj)) {
      sanitized[key] = typeof value === 'string' 
        ? sanitizeString(value) 
        : sanitizeObject(value);
    }
    return sanitized;
  };

  // Apply to mutable objects (be careful with performance!)
  if (req.body) req.body = sanitizeObject(req.body);
  if (req.query) req.query = sanitizeObject(req.query);
  // Note: req.params typically shouldn't be sanitized as it may break routing

  next();
};

// Alternative: Use helmet's content security policy instead of sanitization
// app.use(helmet.contentSecurityPolicy({
