  // Only load from file in non-production environments
  path: process.env.NODE_ENV === 'production' 
    ? undefined 
    : '.env.' + process.env.NODE_ENV
});

// Validate required environment variables at startup
function validateEnvironment() {
  const requiredVars = [
    'PORT',
    'NODE_ENV'
    // Add other required variables for your app
  ];

  const missing = requiredVars.filter(varName => !process.env[varName]);

  if (missing.length > 0) {
    throw new Error(
      `Missing required environment variables: ${missing.join(', ')}. ` +
      'Please check your .env file or environment configuration.'
    );
  }

  // Type validation and conversion examples
  const config = {
    port: parseInt(process.env.PORT) || 3000,
    nodeEnv: process.env.NODE_ENV || 'development',
    // Example: validated API key (never log this!)
    apiKey: process.env.API_KEY || ''
  };

  if (!config.apiKey && process.env.NODE_ENV === 'production') {
    throw new Error('API_KEY is required in production environment');
  }

  return config;
}

// Application initialization with validation
try {
  const config = validateEnvironment();
  console.log(`Starting ${config.nodeEnv} server on port ${config.port}`);

  // ... rest of app setup

} catch (error) {
  console.error('Fatal configuration error:', error.message);
  process.exit(1);
}
