- Set X-Frame-Options, X-Content-Type-Options, etc.

**Code Example**:
```javascript
const express = require('express');
const helmet = require('helmet'); // npm install helmet
const app = express();

// Basic helmet protection
app.use(helmet());

// Advanced CSP configuration
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", "data:", "https:"],
    connectSrc: ["'self'"],
    fontSrc: ["'self'"],
    objectSrc: ["'none'"],
    mediaSrc: ["'self'"],
    frameSrc: ["'none'"]
  }
}));

// Additional security headers
app.use(helmet.referrerPolicy({ policy: 'strict-origin-when-cross-origin' }));
app.use(helmet.hsts({ maxAge: 31536000, includeSubDomains: true, preload: true }));
```

#### 2. **Missing Input Validation and Sanitization** (OWASP A03:2021 - Injection)
**Status**: Not Implemented
**Risk Level**: Low (currently) but establishes dangerous pattern
**Details**: While current routes don't use user input in dangerous ways, the absence of validation creates risk for future development.

**Recommendations**:
- Implement validation middleware for all endpoints accepting user input
- Use express-validator or similar library
- Apply principle of least privilege to inputs

**Code Example**:
```javascript
const express = require('express');
const { body, param, query, validationResult } = require('express-validator'); // npm install express-validator
const app = express();

app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Example validation for user creation
app.post('/users', 
  [
    body('name').trim().isLength({ min: 1, max: 100 }).escape(),
    body('email').isEmail().normalizeEmail(),
    body('age').optional().isInt({ min: 0, max: 150 })
  ], 
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Process validated input safely
    res.status(201).json({ 
      message: 'User created successfully', 
      user: {
        id: Date.now(), // Simplified example
        name: req.body.name,
        email: req.body.email
      }
    });
  }
);

// Example validation for route parameters
app.get('/users/:id',
  [
    param('id').isInt({ min: 1 })
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    res.json({ message: `Fetching user ${req.params.id}` });
  }
);

// Global error handler for validation
app.use((err, req, res, next) => {
  if (err.array) {
    return res.status(400).json({ errors: err.array() });
  }
  next(err);
});
```

#### 3. **Missing Rate Limiting** (OWASP A04:2021 - Insecure Design)
**Status**: Not Implemented
**Risk Level**: Medium
**Details**: No protection against brute force, DoS, or abusive request patterns.

**Recommendations**:
- Implement rate limiting middleware
- Apply different limits based on endpoint sensitivity
- Use distributed stores for multi-instance applications

**Code Example**:
```javascript
const express = require('express');
const rateLimit = require('express-rate-limit'); // npm install express-rate-limit
const app = express();

// General API limiter
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  standardHeaders: true, // Return rate limit info in headers
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' }
});

// Stricter limit for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // Limit each IP to 5 attempts per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many login attempts, please try again after 15 minutes.' }
});

// Apply to all routes
app.use('/api/', apiLimiter);

// Apply stricter limits to auth routes
app.use('/auth/', authLimiter);

// Example protected route
app.post('/auth/login', authLimiter, (req, res) => {
  // Login logic here
  res.json({ message: 'Login successful' });
});
```

#### 4. **Missing CORS Configuration** (OWASP A05:2021 - Security Misconfiguration)
**Status**: Not Implemented
**Risk Level**: Low to Medium (depends on frontend requirements)
**Details**: Default Express behavior may be too permissive or restrictive.

**Recommendations**:
- Configure CORS explicitly based on actual frontend origins
- Restrict methods and headers as needed
- Consider credentials handling requirements

**Code Example**:
```javascript
const express = require('express');
const cors = require('cors'); // npm install cors
const app = express();

// Configure CORS options
const corsOptions = {
  origin: function (origin, callback) {
    // Allow requests from these origins
    const allowedOrigins = [
      'http://localhost:3000',
      'https://yourdomain.com'
    ];

    if (!origin || allowedOrigins.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true, // Allow cookies/auth headers
  maxAge: 86400 // Cache preflight for 24 hours
};

app.use(cors(corsOptions));

// For API-only services with no frontend:
// app.use(cors({ origin: false })); // Disable CORS entirely

// Routes
app.get('/api/health', (req, res) => {
  res.json({ status: 'ok' });
});
```

#### 5. **Missing Comprehensive Error Handling** (OWASP A09:2021 - Security Logging and Monitoring Failures)
**Status**: Not Implemented
**Risk Level**: Medium
**Details**: No centralized error handling that could leak stack traces or fail to log security events properly.

**Recommendations**:
- Implement centralized error handling middleware
- Log errors appropriately without exposing sensitive information
- Differentiate between development and production error responses
- Handle asynchronous errors properly

**Code Example**:
```javascript
const express = require('express');
const app = express();
const winston = require('winston'); // npm install winston

// Configure logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'user-service' },
  transports: [
    new winston.transports.Console({
      format: winston.format.simple()
    }),
    new winston.transports.File({ filename: 'error.log', level: 'error' })
  ]
});

// Middleware to log requests
app.use((req, res, next) => {
  logger.info(`[${new Date().toISOString()}] ${req.method} ${req.path}`, {
    ip: req.ip,
    userAgent: req.get('User-Agent')
  });
  next();
});

// 404 handler
app.use((req, res) => {
  logger.warn(`Route not found: ${req.method} ${req.path} from ${req.ip}`);
  res.status(404).json({ 
    error: 'Not Found',
    message: 'The requested resource could not be found.'
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  // Log error details for internal use
  logger.error(`${err.message}`, {
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    method: req.method,
    url: req.originalPath,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Determine status code
  const status = err.status || 500;

  // Production vs development error responses
  if (process.env.NODE_ENV === 'production') {
    // Don't leak internal details in production
    res.status(status).json({
      error: status >= 500 ? 'Internal Server Error' : 'Bad Request',
      message: status === 500 
        ? 'An unexpected error occurred' 
        : err.message || 'Invalid request'
    });
  } else {
    // More detailed errors in development
    res.status(status).json({
      error: err.message || 'Error',
      message: err.message,
      stack: err.stack
    });
  }
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', { promise, reason });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception:', { error });
  process.exit(1);
});

// Routes
app.get('/api/test-error', (req, res) => {
  // This will trigger the error handler
  throw new Error('Test error message');
});
```

#### 6. **Missing HTTP Security Best Practices**
**Status**: Partially Implemented
**Risk Level**: Low
**Details**: Basic routing but missing method-specific handling and security considerations.

**Recommendations**:
- Be explicit about HTTP methods for each endpoint
- Implement proper HTTP status codes
- Consider implementing security.txt for vulnerability reporting

**Code Example**:
```javascript
const express = require('express');
const app = express();

// Instead of app.get(), be explicit about methods
app.route('/api/users')
  .get((req, res) => {
    // GET handler - retrieve users
    res.json({ 
      users: [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' }
      ]
    });
  })
  .post((req, res) => {
    // POST handler - create user
    // Would include validation middleware here
    res.status(201).json({ 
      message: 'User created', 
      userId: Date.now() 
    });
  })
  .put((req, res) => {
    // PUT handler - replace/update
    res.status(405).json({ 
      error: 'Method Not Allowed', 
      message: 'Use POST to create or PATCH to update' 
    });
  })
  .delete((req, res) => {
    // DELETE handler
    res.status(405).json({ 
      error: 'Method Not Allowed', 
      message: 'DELETE operation not supported on collection' 
    });
  })
  .all((req, res) => {
    // Handle any other methods
    res.status(405).json({ 
      error: 'Method Not Allowed', 
      message: `Method ${req.method} not allowed for this endpoint` 
    });
  });

// Individual resource handling
app.route('/api/users/:id')
  .get((req, res) => {
    // GET specific user
    res.json({ 
      user: { id: req.params.id, name: 'Example User', email: 'user@example.com' } 
    });
  })
  .patch((req, res) => {
    // PATCH - partial update
    res.json({ 
      message: `User ${req.params.id} partially updated` 
    });
  })
  .delete((req, res) => {
    // DELETE - remove user
    res.status(204).send(); // No Content
  })
  .all((req, res) => {
    res.status(405).json({ 
      error: 'Method Not Allowed' 
    });
  });

// Security.txt endpoint for vulnerability reporting (RFC 5785)
app.get('/.well-known/security.txt', (req, res) => {
  res.set('Content-Type', 'text/plain');
  res.send(`
